const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for Kerala and Sri Lanka
  const kerala = ee.Geometry.Rectangle([74.1, 8.1, 77.5, 12.2]);
  const sriLanka = ee.Geometry.Rectangle([80.0, 5.9, 81.9, 7.7]);

  // 2. Load CHIRPS daily precipitation data for July-August 2018
  const startDate = ee.Date('2018-07-01');
  const endDate = ee.Date('2018-08-31');

  const chirps = ee.ImageCollection('UCSB/CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate);

  // Check if collection has data
  const size = chirps.size().getInfo();
  print('CHIRPS images found (Jul-Aug 2018): ' + size);

  if (size === 0) {
    print('No data found for July-August 2018');
    print('<answer>C1</answer>');
    return;
  }

  // 3. Sum up total precipitation for both regions
  const totalPrecip = chirps.reduce(ee.Reducer.sum());

  // 4. Calculate mean/total rainfall for Kerala
  const keralaStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: kerala,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const keralaRainfall = keralaStats.precipitation;

  // 5. Calculate mean/total rainfall for Sri Lanka
  const sriLankaStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: sriLanka,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const sriLankaRainfall = sriLankaStats.precipitation;

  // 6. Validation checks
  print('Kerala mean rainfall (mm): ' + (keralaRainfall ? keralaRainfall.toFixed(2) : 'null'));
  print('Sri Lanka mean rainfall (mm): ' + (sriLankaRainfall ? sriLankaRainfall.toFixed(2) : 'null'));

  if (keralaRainfall === null || keralaRainfall === undefined || 
      sriLankaRainfall === null || sriLankaRainfall === undefined) {
    print('Calculation failure: null or undefined values');
    print('<answer>C3</answer>');
    return;
  }

  if (isNaN(keralaRainfall) || isNaN(sriLankaRainfall)) {
    print('Invalid values (NaN) in rainfall calculation');
    print('<answer>C3</answer>');
    return;
  }

  // 7. Compare rainfall
  const difference = keralaRainfall - sriLankaRainfall;
  print('Difference (Kerala - Sri Lanka): ' + difference.toFixed(2) + ' mm');

  if (keralaRainfall > sriLankaRainfall) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
